25: function parseAction(record) {
26:   if (!record || typeof record.text !== "string") return null;
27:   let value;
28:   try { value = JSON.parse(record.text); } catch { return null; }
29:   const aliases = { read_file: "read", list_dir: "list_files", edit_file: "edit", run_test: "test", apply_patch: "edit" };
30:   if (typeof value.action === "string") return { action: aliases[value.action] || value.action, args: value.args && typeof value.args === "object" ? value.args : Object.fromEntries(Object.entries(value).filter(([key]) => !["action", "reason"].includes(key))), reason: value.reason || "provider selected this next tool move" };
31:   if (typeof value.command === "string") return { action: aliases[value.command] || value.command, args: Object.fromEntries(Object.entries(value).filter(([key]) => !["command", "reason"].includes(key))), reason: value.reason || "provider selected this next tool move" };
32:   for (const name of ["list_files", "list_dir", "search", "read", "read_file", "edit", "edit_file", "test", "run_test", "finish"]) {
33:     if (value[name] !== undefined) return { action: aliases[name] || name, args: value[name] && typeof value[name] === "object" ? value[name] : {}, reason: value.reason || "provider selected this next tool move" };
