72: function integrateCandidate(source, candidate, verifyCommand, acceptanceCommand) {
73:   const backups = [];
74:   for (const change of candidate.changes) {
75:     const target = resolve(source, change.path);
76:     const currentExists = existsSync(target), current = currentExists ? readFileSync(target) : Buffer.alloc(0);
77:     if (currentExists !== change.before.existed || digest(current) !== change.before.digest) {
78:       return { integrated: false, classification: "protected-border", reason: `source changed since isolation: ${change.path}` };
79:     }
80:     backups.push({ target, existed: currentExists, bytes: current });
81:   }
82:   try {
83:     for (const change of candidate.changes) {
84:       const target = resolve(source, change.path), temporary = `${target}.union-dev-${process.pid}`;
85:       mkdirSync(dirname(target), { recursive: true });
86:       writeFileSync(temporary, change.after);
87:       renameSync(temporary, target);
88:     }
89:     const verification = runTestsCommand(source, verifyCommand);
90:     const acceptance = acceptanceCommand === verifyCommand ? verification : runTestsCommand(source, acceptanceCommand);
91:     if (verification.passed && acceptance.passed) return { integrated: true, classification: "repair", verification, acceptance };
92:     for (const backup of backups) backup.existed ? writeFileSync(backup.target, backup.bytes) : rmSync(backup.target, { force: true });
93:     return { integrated: false, classification: "repair-rejected", reason: "verification or objective acceptance failed after integration", verification, acceptance };
94:   } catch (error) {
95:     for (const backup of backups) backup.existed ? writeFileSync(backup.target, backup.bytes) : rmSync(backup.target, { force: true });
96:     return { integrated: false, classification: "repair-rejected", reason: error.message };
97:   }
98: }
